// Build step: bundle editor-entry.mjs into a single IIFE (so there is exactly
// one @codemirror/state instance) and emit it as a TS string constant the app
// inlines into the WebView HTML (html.ts). Re-run whenever editor-entry.mjs
// changes:  node src/lib/cm/build-bundle.mjs
import { build } from "esbuild";
import { writeFileSync } from "node:fs";

const result = await build({
  entryPoints: ["src/lib/cm/editor-entry.mjs"],
  bundle: true,
  format: "iife",
  minify: true,
  target: "safari15",
  write: false,
});
const code = result.outputFiles[0].text;
const out = `// AUTO-GENERATED by src/lib/cm/build-bundle.mjs — do not edit by hand.\n/* eslint-disable */\nexport const CM_BUNDLE = ${JSON.stringify(code)};\n`;
writeFileSync("src/lib/cm/bundle.ts", out);
console.log(`wrote src/lib/cm/bundle.ts (${(code.length / 1024) | 0} KB)`);
